@@ -0,0 +1,55 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { fresh, NOW } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}` });
+
+test("authentication and roles protect reads and writes", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const authorization of [undefined, "Bearer unknown", "Basic seed-manager", "Bearer "]) {
+    const res = await handle({ path: "/items", headers: { Authorization: authorization } });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+  }
+  for (const role of ["viewer", "cook", "manager"]) {
+    assert.equal((await handle({ path: "/items", headers: headers(role) })).status, 200);
+  }
+  const before = structuredClone(store.data);
+  const denied = await handle({ method: "POST", path: "/recipes/1/cook", headers: headers("viewer"), body: { portions: 4 } });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.deepEqual(store.data, before);
+  for (const role of ["viewer", "cook"]) {
+    assert.equal((await handle({ path: "/audit", headers: headers(role) })).status, 403);
+    for (const path of ["/orders", "/stocktakes", "/stocktakes/1/finish", "/jobs/nightly"]) {
+      assert.equal((await handle({ method: "POST", path, headers: headers(role) })).status, 403);
+    }
+  }
+});
+
+test("cook actions are audited once with the persisted response status", async () => {
+  const store = fresh();
+  const saved = [];
+  store.save = () => saved.push(structuredClone(store.data));
+  const handle = createApp(store, { clock: () => NOW });
+  const request = (path, body, role = "cook") => handle({ method: "POST", path, body, headers: headers(role) });
+  assert.equal((await request("/recipes/1/cook", { portions: 4 })).status, 200);
+  assert.equal((await request("/batches/1/waste", { qty: 0.1 })).status, 201);
+  assert.equal((await request("/temperatures", { location: "fridge", celsius: 3 })).status, 201);
+  const take = await request("/stocktakes", { location: "dry" }, "manager");
+  assert.equal(take.status, 201);
+  assert.equal((await request(`/stocktakes/${take.body.id}/counts`, { batchId: 1, counted: 2 })).status, 200);
+  assert.equal(saved.length, 5);
+  assert.equal(saved[0].audit.length, 1);
+  assert.deepEqual(saved[0].audit[0], {
+    time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: "/recipes/1/cook", status: 200,
+  });
+  const audit = await handle({ path: "/audit", headers: headers("manager") });
+  assert.equal(audit.status, 200);
+  assert.deepEqual(audit.body, [...store.data.audit].reverse());
+  assert.equal((await request("/recipes/2/cook", { portions: 100 })).status, 409);
+  assert.equal(saved.length, 5);
+  assert.equal(store.data.audit.length, 5);
+});
